def longest_strictly_increasing_prefix_length(arr):
    if not arr:
        return 0
    length = 1
    for i in range(1, len(arr)):
        if arr[i] > arr[i - 1]:
            length += 1
        else:
            break
    return length

def longest_sorted_suffix_length(arr):
    n = len(arr)
    if n == 0:
        return 0
    length = 1
    for i in range(n - 2, -1, -1):
        if arr[i] <= arr[i + 1]:
            length += 1
        else:
            break
    return length

