def longest_sorted_run_length(arr):
    n = len(arr)
    if n == 0:
        return 0
    max_len = 1
    cur = 1
    for i in range(1, n):
        if arr[i] >= arr[i - 1]:
            cur += 1
        else:
            cur = 1
        max_len = max(max_len, cur)
    return max_len

def extract_longest_sorted_prefix(arr):
    if not arr:
        return []
    length = 1
    for i in range(1, len(arr)):
        if arr[i] >= arr[i - 1]:
            length += 1
        else:
            break
    return arr[:length]

def interleave_two_rankings(list1, list2):
    result = []
    seen = set()
    i, j = 0, 0
    n1, n2 = len(list1), len(list2)
    turn = 0
    while i < n1 or j < n2:
        if turn == 0:
            if i < n1:
                item = list1[i]
                i += 1
                if item not in seen:
                    seen.add(item)
                    result.append(item)
            turn = 1
        else:
            if j < n2:
                item = list2[j]
                j += 1
                if item not in seen:
                    seen.add(item)
                    result.append(item)
            turn = 0
    return result

def average_rank_across_two_lists(list1, list2):
    pos1 = {item: idx for idx, item in enumerate(list1)}
    pos2 = {item: idx for idx, item in enumerate(list2)}
    common = [item for item in list1 if item in pos2]
    avg = {item: (pos1[item] + pos2[item]) / 2 for item in common}
    return sorted(common, key=lambda x: (avg[x], x))

def sort_by_consonant_count(words):
    vowels = set('aeiouAEIOU')

    def consonant_count(w):
        return sum(1 for c in w if c.isalpha() and c not in vowels)

    return sorted(words, key=lambda w: (-consonant_count(w), w))

def weighted_score_rank(records):
    def avg(scores):
        return sum(scores) / len(scores)

    sorted_records = sorted(records, key=lambda r: (-avg(r[1]), r[0]))
    return [r[0] for r in sorted_records]

def rank_percentile_bucket(scores):
    result = []
    for s in scores:
        if s >= 75:
            result.append('Q4')
        elif s >= 50:
            result.append('Q3')
        elif s >= 25:
            result.append('Q2')
        else:
            result.append('Q1')
    return result

def sort_by_distance_from_mean(nums):
    mean = sum(nums) / len(nums)
    return sorted(nums, key=lambda x: (abs(x - mean), x))

def bucket_sort_by_string_length(strings, ranges):
    buckets = [[] for _ in ranges]
    for s in strings:
        length = len(s)
        for idx, (lo, hi) in enumerate(ranges):
            if lo <= length <= hi:
                buckets[idx].append(s)
                break
    return [sorted(b) for b in buckets]
